type Routine = { name: string; steps: Step[] };
const examples: Preset[] = [
  { id: 1, name: "Easy start", bpm: 60, meter: "4/4", subdivision: "Quarter", favourite: true },
  { id: 2, name: "Build the pulse", bpm: 72, meter: "4/4", subdivision: "Eighths", favourite: true },
  { id: 3, name: "Find your flow", bpm: 84, meter: "4/4", subdivision: "Quarter", favourite: false }
];
const starter: Routine = { name: "A steady warm-up", steps: examples.map(preset => ({ id: `starter-${preset.id}`, preset, goal: "Minutes", amount: 2 })) };
